package com.google.javascript.jscomp;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.base.Charsets;
import com.google.common.io.CharStreams;
import com.google.common.io.Files;
import com.google.javascript.jscomp.SourceFile;
import com.google.javascript.rhino.jstype.StaticSourceFile;
import java.io.*;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Serializable;
import java.io.StringReader;
import java.math.*;
import java.nio.charset.Charset;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class SourceFile_getLine_TriageGen2Test {

    /**
     * Since SourceFile is a complex class and getCode() is called internally,
     * we use the static factory method fromCode to provide controlled input.
     */

    @Test
    public void testGetLine_Success() {
        String code = "line1\nline2\nline3\nline4";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        assertEquals("line1", sourceFile.getLine(1));
        assertEquals("line2", sourceFile.getLine(2));
        assertEquals("line3", sourceFile.getLine(3));
        assertEquals("line4", sourceFile.getLine(4));
    }

    @Test
    public void testGetLine_WithCachingOptimization() {
        String code = "line1\nline2\nline3\nline4";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Test the optimization: lineNumber >= lastLine
        // First call sets lastLine = 1, lastOffset = 0
        sourceFile.getLine(1);
        // Second call: lineNumber (2) >= lastLine (1)
        assertEquals("line2", sourceFile.getLine(2));
        // Third call: lineNumber (3) >= lastLine (2)
        assertEquals("line3", sourceFile.getLine(3));
    }

    @Test
    public void testGetLine_InvalidLineNumber_ReturnsNull() {
        String code = "line1\nline2";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Requesting a line that doesn't exist (too high)
        assertNull(sourceFile.getLine(3));
    }

    @Test
    public void testGetLine_EndOfFileLogic() {
        // Case: pos reaches the end of file (no newline after last line)
        // The implementation returns null if js.indexOf('\n', pos) == -1
        String code = "line1\nline2";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Line 1 is fine
        assertEquals("line1", sourceFile.getLine(1));
        // Line 2: pos will be at the start of "line2". 
        // indexOf('\n', pos) will find the newline after line1? 
        // Wait, let's trace: 
        // line 1: pos=0, startLine=1. loop n=1 to 1 (no loop). 
        // lastOffset=0, lastLine=1. 
        // js.indexOf('\n', 0) is 5. returns js.substring(0, 5) -> "line1"

        // Let's test line 2:
        // n=1; startLine=1; lastLine=1; pos=0;
        // loop n=1; n < 2: nextpos = 5. pos = 6.
        // lastOffset=6, lastLine=2.
        // js.indexOf('\n', 6) is -1. Returns null.
        // Note: The implementation logic seems to return null for the last line if it doesn't end with \n
        assertNull(sourceFile.getLine(2));
    }

    @Test
    public void testGetLine_SingleLineNoNewline() {
        String code = "line1";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // pos=0, startLine=1. loop n=1 to 1 (no loop).
        // lastOffset=0, lastLine=1.
        // js.indexOf('\n', 0) is -1. Returns null.
        assertNull(sourceFile.getLine(1));
    }

    @Test
    public void testGetLine_IOException() {
        // We use Mockito to simulate an IOException in getCode()
        // Since SourceFile is likely not final and getCode is public, we mock it.
        SourceFile mockSourceFile = Mockito.mock(SourceFile.class);
        try {
            Mockito.when(mockSourceFile.getCode()).thenThrow(new IOException("Simulated IO error"));
        } catch (IOException e) {
            // Ignore
        }

        // The catch block returns null
        assertNull(mockSourceFile.getLine(1));
    }

    @Test
    public void testGetLine_JumpBackwards() {
        // The current implementation doesn't explicitly handle lineNumber < lastLine 
        // for resetting the pointer, it just uses startLine=1 and pos=0 because 
        // the 'if (lineNumber >= lastLine)' fails.
        String code = "line1\nline2\nline3";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        sourceFile.getLine(2); // Sets lastLine = 2
        // Request line 1 (lineNumber < lastLine)
        // pos = 0, startLine = 1.
        assertEquals("line1", sourceFile.getLine(1));
    }
}
